using LittleLeo.Events;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "BattleSetup", menuName = "Data/BattleSceneSetups/BattleSetup", order = 0)]
public class BattleSetup : BattleSceneSetup
{
	[SerializeField]
	private VoidEvent OnStopCurrentBGM;

	public override void SetupScene()
	{
		OnStopCurrentBGM.Raise();
		ReferenceSingleton<GameStateManager>.Instance.CheckSothisTutorial();
		base.SetupScene();
		ReferenceSingleton<BattleHandler>.Instance.InitializeBattle(ambushBattle: false, resetDiceBadAndDiscard: true);
	}

	public void InstantiateAmbushBattleScene()
	{
		OnStopCurrentBGM.Raise();
		base.SetupScene();
		ReferenceSingleton<BattleHandler>.Instance.InitializeBattle(ambushBattle: true, resetDiceBadAndDiscard: true);
	}

	public override void PlayBGM()
	{
	}
}
